  select 'keep:user_roles policies (who can read or change grants)', v.value, null::boolean from (select (select md5(coalesce(string_agg(policyname || ':' || cmd || ':' || coalesce(qual, '') || ':' || coalesce(with_check, ''), E'\n' order by policyname), '')) from pg_policies where schemaname = 'public' and tablename = 'user_roles') as value) v
