  select 'chg:inv_company_settings: the switch column is added', v.value, null::boolean from (select (select coalesce((select format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text || ':' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') from pg_attribute a left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum where a.attrelid = 'public.inv_company_settings'::regclass and a.attname = 'project_notes_enabled' and not a.attisdropped), 'absent')) as value) v
