  select 'keep:inv_company_settings: every column except the switch', v.value, null::boolean from (select (select md5(coalesce(string_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text || ':' || coalesce(pg_get_expr(d.adbin, d.adrelid), ''), E'\n' order by a.attname), '')) from pg_attribute a left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum where a.attrelid = 'public.inv_company_settings'::regclass and a.attnum > 0 and not a.attisdropped and a.attname <> 'project_notes_enabled') as value) v
