  select 'keep:inv_company_settings: constraints, indexes, policies, triggers and privileges', v.value, null::boolean from (select (select md5(coalesce((select string_agg(c.conname || pg_get_constraintdef(c.oid), E'\n' order by c.conname) from pg_constraint c where c.conrelid = 'public.inv_company_settings'::regclass), '') || coalesce((select string_agg(indexdef, E'\n' order by indexname) from pg_indexes where schemaname = 'public' and tablename = 'inv_company_settings'), '') || coalesce((select string_agg(policyname || cmd || coalesce(qual, ''), E'\n' order by policyname) from pg_policies where schemaname = 'public' and tablename = 'inv_company_settings'), '') || coalesce((select string_agg(pg_get_triggerdef(t.oid), E'\n' order by t.tgname) from pg_trigger t where t.tgrelid = 'public.inv_company_settings'::regclass and not t.tgisinternal), '') || coalesce((select relacl::text from pg_class where oid = 'public.inv_company_settings'::regclass), ''))) as value) v
  union all
  select 'keep:inv_reference_counters: columns, policies and privileges', v.value, null::boolean from (select (select md5(coalesce((select string_agg(a.attname || format_type(a.atttypid, a.atttypmod) || a.attnotnull::text, E'\n' order by a.attname) from pg_attribute a where a.attrelid = 'public.inv_reference_counters'::regclass and a.attnum > 0 and not a.attisdropped), '') || coalesce((select string_agg(policyname, E'\n' order by policyname) from pg_policies where schemaname = 'public' and tablename = 'inv_reference_counters'), '') || coalesce((select relacl::text from pg_class where oid = 'public.inv_reference_counters'::regclass), ''))) as value) v
  union all
  select 'keep:the existing counters (unit, stock, request, transfer, movement, count) are not touched', v.value, null::boolean from (select (select coalesce(string_agg(kind || '=' || last_value, ',' order by company_id, kind), 'none') from inv_reference_counters where kind in ('unit', 'stock', 'request', 'transfer', 'movement', 'count')) as value) v
