  select 'keep:companies with the dispatch-note switch ON (must be 0)', v.value, ((select count(*) from inv_company_settings s where (to_jsonb(s)->>'project_notes_enabled')::boolean is true) = 0) from (select (select count(*)::text from inv_company_settings s where (to_jsonb(s)->>'project_notes_enabled')::boolean is true) as value) v
  union all
  select 'keep:scheduler: pg_cron job definitions (cron.job)', v.value, null::boolean from (select (select case when to_regclass('cron.job') is null then 'not present' when not has_table_privilege(current_user, 'cron.job', 'select') then 'not readable' else (xpath('/row/v/text()', query_to_xml('select count(*)::text || '':'' || md5(coalesce(string_agg(to_jsonb(j)::text, ''|'' order by j.jobid), '''')) as v from cron.job j', false, true, '')))[1]::text end) as value) v
  union all
  select 'keep:installed extensions', v.value, null::boolean from (select (select md5(coalesce(string_agg(extname || ':' || extversion, ',' order by extname), '')) from pg_extension) as value) v
