  select 'pre:m01', case when exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'inv_issue_to_employee' and prosrc like '%reserved for THIS request%') then 'applied' else 'absent' end, exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname = 'inv_issue_to_employee' and prosrc like '%reserved for THIS request%')
