prereq as (
  select 'base' as pack, grp, chk, item, result, detail from (
with eight(name) as (values ('crm_grant_access'), ('crm_revoke_access'), ('proj_grant_access'), ('proj_revoke_access'), ('inv_grant_access'), ('inv_revoke_access'), ('pbx_grant_access'), ('pbx_revoke_access')),
tables(name) as (values ('crm_company_grants'), ('proj_company_grants'), ('inv_company_grants'), ('pbx_company_grants')),
fn as (select p.oid, p.proname, p.prosrc, p.prosecdef, p.proconfig from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in (select name from eight)),
-- text that must be present in each function: the new rule (N) or an earlier protection that must survive (E)
needs(fname, kind, label, needle) as (values
  ('pbx_grant_access', 'N', 'R1: only an approver gives or removes the approver right', 'Only a CEO / CTO approver of this company can give or remove the approver right'),
  ('pbx_grant_access', 'N', 'R1: the last eligible approver is protected', 'last eligible CEO / CTO approver of this company'),
  ('pbx_grant_access', 'N', 'R2: nobody adds a right to their own grant', 'You cannot add rights to your own access'),
  ('pbx_grant_access', 'N', 'changes are serialised per company', 'pg_advisory_xact_lock'),
  ('pbx_grant_access', 'E', 'the last access manager is protected', 'last person who holds it for this company'),
  ('pbx_grant_access', 'E', 'only access managers grant', 'budget access management for this company can grant'),
  ('pbx_revoke_access', 'N', 'R1: only an approver withdraws an approver', 'Only a CEO / CTO approver of this company can withdraw an approver'),
  ('pbx_revoke_access', 'N', 'R1: the last eligible approver is protected', 'Cannot remove the last eligible CEO / CTO approver'),
  ('pbx_revoke_access', 'N', 'changes are serialised per company', 'pg_advisory_xact_lock'),
  ('pbx_revoke_access', 'E', 'the last access manager is protected', 'last person who manages access to project budgets'),
  ('crm_grant_access', 'N', 'R2: nobody adds a right to their own grant', 'You cannot add rights to your own access'),
  ('crm_grant_access', 'N', 'R3: a non-founder cannot replace another access manager', 'or access manager'),
  ('crm_grant_access', 'E', 'only a founder hands out founder or access management', 'Only a CRM founder can grant founder or access-management rights'),
  ('crm_grant_access', 'E', 'the last founder is protected', 'last founder'),
  ('crm_revoke_access', 'N', 'R3: a non-founder cannot withdraw another access manager', 'Only a CRM founder can withdraw an access manager'),
  ('crm_revoke_access', 'E', 'the last founder is protected', 'Cannot revoke the last founder'),
  ('proj_revoke_access', 'N', 'R3: a non-founder cannot withdraw another access manager', 'Only a Projects founder can withdraw an access manager'),
  ('proj_revoke_access', 'E', 'the last founder is protected', 'Cannot revoke the last founder'),
  ('proj_revoke_access', 'E', 'a live Project Manager cannot be withdrawn', 'Project Manager of a live project'),
  ('proj_revoke_access', 'E', 'a live department head cannot be withdrawn', 'heads a department team on a live project'),
  ('proj_grant_access', 'E', 'an access manager is changed only by a founder (unchanged)', 'Only a Projects founder can change a founder'),
  ('inv_revoke_access', 'N', 'R3: a non-founder cannot withdraw an access manager or cost reader', 'Only an Inventory founder can withdraw an access manager or a cost reader'),
  ('inv_revoke_access', 'E', 'the last founder is protected', 'Cannot revoke the last founder'),
  ('inv_revoke_access', 'E', 'operator locations are closed with the access', 'inv_operator_locations'),
  ('inv_grant_access', 'E', 'cost visibility needs a founder (unchanged)', 'or cost reader')
),
checks as (
  -- 1 the eight functions ------------------------------------------------------------------------------------------------
  select 1 as grp, 'function exists' as chk, e.name as item, case when f.oid is not null then 'OK' else 'FAIL' end as result, '' as detail
  from eight e left join fn f on f.proname = e.name
  union all
  select 1, 'security definer with a fixed search path', f.proname,
         case when f.prosecdef and coalesce(f.proconfig::text, '') like '%search_path=public%' then 'OK' else 'FAIL' end, coalesce(f.proconfig::text, 'no search_path set')
  from fn f
  union all
  select 1, 'signed-in users can call it, anonymous visitors cannot', f.proname,
         case when has_function_privilege('authenticated', f.oid, 'execute') and not has_function_privilege('anon', f.oid, 'execute') then 'OK' else 'FAIL' end,
         'authenticated ' || has_function_privilege('authenticated', f.oid, 'execute')::text || ', anon ' || has_function_privilege('anon', f.oid, 'execute')::text
  from fn f
  -- 2 the rules ----------------------------------------------------------------------------------------------------------
  union all
  select 2, case n.kind when 'N' then 'new rule present' else 'earlier protection still present' end, n.fname || ': ' || n.label,
         case when position(n.needle in f.prosrc) > 0 then 'OK' else 'FAIL' end,
         case when position(n.needle in f.prosrc) > 0 then '' else case n.kind when 'N' then 'the new rule is missing: is the migration applied?' else 'an earlier protection is missing' end end
  from needs n left join fn f on f.proname = n.fname
  -- 3 nothing else can write a grant table ----------------------------------------------------------------------------------
  union all
  select 3, 'writes a grant table', p.proname, case when p.proname in (select name from eight) then 'OK' else 'FAIL' end,
         case when p.proname in (select name from eight) then '' else 'a function outside the expected eight can write a grant table' end
  from pg_proc p
  where p.pronamespace = 'public'::regnamespace and p.prokind = 'f'
    and exists (select 1 from tables t where p.prosrc ~* ('(insert\s+into|update|delete\s+from)\s+(public\.)?' || t.name || '\M'))
  union all
  select 3, 'builds SQL dynamically naming a grant table', p.proname, 'FAIL', 'a function runs dynamic SQL that names a grant table'
  from pg_proc p
  where p.pronamespace = 'public'::regnamespace and p.prokind = 'f' and p.prosrc ~* '\mexecute\M'
    and exists (select 1 from tables t where p.prosrc ilike '%' || t.name || '%')
  union all
  select 3, 'no trigger changes rights', c.relname || ' / ' || t.tgname, case when t.tgname ~* 'audit|updated_at' then 'OK' else 'FAIL' end, pg_get_triggerdef(t.oid)
  from pg_trigger t join pg_class c on c.oid = t.tgrelid
  where not t.tgisinternal and c.relname in (select name from tables)
  -- 4 the tables -------------------------------------------------------------------------------------------------------------
  union all
  select 4, 'row-level security on', t.name, case when c.relrowsecurity then 'OK' else 'FAIL' end, ''
  from tables t join pg_class c on c.oid = to_regclass('public.' || t.name)
  union all
  select 4, 'only a read policy', t.name || ' / ' || p.policyname, case when p.cmd = 'SELECT' then 'OK' else 'FAIL' end, p.cmd
  from tables t join pg_policies p on p.schemaname = 'public' and p.tablename = t.name
  union all
  select 4, 'signed-in and anonymous users cannot write it directly', t.name,
         case when has_table_privilege('authenticated', c.oid, 'insert, update, delete, truncate') or has_table_privilege('anon', c.oid, 'select, insert, update, delete, truncate') then 'FAIL' else 'OK' end,
         'authenticated can read: ' || has_table_privilege('authenticated', c.oid, 'select')::text
  from tables t join pg_class c on c.oid = to_regclass('public.' || t.name)
  -- 5 counts -----------------------------------------------------------------------------------------------------------------
  union all select 5, 'active grants (information only)', 'Sales', 'INFO', (select count(*)::text from crm_company_grants where revoked_at is null)
  union all select 5, 'active grants (information only)', 'Projects', 'INFO', (select count(*)::text from proj_company_grants where revoked_at is null)
  union all select 5, 'active grants (information only)', 'Inventory', 'INFO', (select count(*)::text from inv_company_grants where revoked_at is null)
  union all select 5, 'active grants (information only)', 'Budget', 'INFO', (select count(*)::text from pbx_company_grants where revoked_at is null)
  union all select 5, 'Budget approvers per company (eligible = active)', c.legal_name, 'INFO',
         count(*) filter (where 'executive_approver' = any (g.capabilities) and p.is_active)::text || ' eligible of ' || count(*) filter (where 'executive_approver' = any (g.capabilities))::text
  from companies c join pbx_company_grants g on g.company_id = c.id and g.revoked_at is null join profiles p on p.id = g.user_id group by c.id, c.legal_name
)
select grp, chk, item, result, detail from checks
  ) v_base
  union all
  select 'm01' as pack, grp, chk, item, result, detail from (
with fns(name) as (values ('inv_issue_to_employee')),
fn as (select p.oid, p.proname, p.prosrc, p.prosecdef, p.proconfig from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in (select name from fns)),
needs(fname, kind, label, needle) as (values
  ('inv_issue_to_employee', 'N', 'a unit reserved for THIS request is not a conflict', 'inv_unit_reserved_by(u.id, now(), p_expected_return_at, q.id)'),
  ('inv_issue_to_employee', 'N', 'a unit''s reservation for this request is consumed', 'inv_reservation_take(q.id, u.item_id, u.id, 1, null)'),
  ('inv_issue_to_employee', 'N', 'counted stock: this request''s reservation is consumed first', 'inv_reservation_take(q.id, i.id, null, v_qty, l.id)'),
  ('inv_issue_to_employee', 'N', 'an issued-in-full reservation is completed', 'set status = ''completed'''),
  ('inv_issue_to_employee', 'E', 'a unit reserved for ANOTHER request still refuses', 'is reserved for % and cannot be issued to a person for that period'),
  ('inv_issue_to_employee', 'E', 'counted stock reserved for others still refuses', 'can be issued now: the rest is not on the shelf or is reserved for upcoming requests'),
  ('inv_issue_to_employee', 'E', 'the request must be for this employee', 'That request is not for this employee'),
  ('inv_issue_to_employee', 'E', 'the expected return must be in the future', 'The expected return date must be in the future'),
  ('inv_issue_to_employee', 'E', 'no more than the request asks for', 'and they have all been issued'),
  ('inv_issue_to_employee', 'E', 'replay returns the original result', '(h->>''replay'')::boolean'),
  ('inv_issue_to_employee', 'E', 'the movement is written through the ledger helpers', 'inv_ml(v_mid')
),
checks as (
  select 1 as grp, 'function exists' as chk, e.name as item, case when f.oid is not null then 'OK' else 'FAIL' end as result, '' as detail
  from fns e left join fn f on f.proname = e.name
  union all
  select 1, 'security definer with a fixed search path', f.proname,
         case when f.prosecdef and coalesce(f.proconfig::text, '') like '%search_path=public%' then 'OK' else 'FAIL' end, coalesce(f.proconfig::text, 'no search_path set')
  from fn f
  union all
  select 1, 'signed-in users can call it, anonymous visitors cannot', f.proname,
         case when has_function_privilege('authenticated', f.oid, 'execute') and not has_function_privilege('anon', f.oid, 'execute') then 'OK' else 'FAIL' end,
         'authenticated ' || has_function_privilege('authenticated', f.oid, 'execute')::text || ', anon ' || has_function_privilege('anon', f.oid, 'execute')::text
  from fn f
  union all
  select 2, case n.kind when 'N' then 'new rule present' else 'earlier protection still present' end, n.fname || ': ' || n.label,
         case when f.oid is null then 'FAIL' when position(n.needle in f.prosrc) > 0 then 'OK' else 'FAIL' end,
         case when f.oid is null then 'function missing' when position(n.needle in f.prosrc) > 0 then '' else 'text not found: ' || n.needle end
  from needs n left join fn f on f.proname = n.fname
)
select grp, chk, item, result, detail from checks
  ) v_m01
  union all
  select 'm02' as pack, grp, chk, item, result, detail from (
with fns(name) as (values ('proj_propose_scope_change')),
fn as (select p.oid, p.proname, p.prosrc, p.prosecdef, p.proconfig from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in (select name from fns)),
needs(fname, kind, label, needle) as (values
  ('proj_propose_scope_change', 'N', 'founders and approve_scope holders are told', '''project_scope_proposed'''),
  ('proj_propose_scope_change', 'N', 'one notice per proposal (dedupe key)', '''scopechange:'' || v_id || '':proposed'''),
  ('proj_propose_scope_change', 'N', 'only people who can act (the usual proj_notify rule)', 'proj_notify(v.id, g.user_id'),
  ('proj_propose_scope_change', 'E', 'only the project manager (or founder) may propose', 'proj_require_manager(v)'),
  ('proj_propose_scope_change', 'E', 'the project must be open', 'proj_require_open_project(v)'),
  ('proj_propose_scope_change', 'E', 'a title is required', 'Give the change a title'),
  ('proj_propose_scope_change', 'E', 'a proposed scope is required', 'Write the proposed scope'),
  ('proj_propose_scope_change', 'E', 'the cost effect stays in its own restricted table', 'insert into proj_scope_change_commercial')
),
checks as (
  select 1 as grp, 'function exists' as chk, e.name as item, case when f.oid is not null then 'OK' else 'FAIL' end as result, '' as detail
  from fns e left join fn f on f.proname = e.name
  union all
  select 1, 'security definer with a fixed search path', f.proname,
         case when f.prosecdef and coalesce(f.proconfig::text, '') like '%search_path=public%' then 'OK' else 'FAIL' end, coalesce(f.proconfig::text, 'no search_path set')
  from fn f
  union all
  select 1, 'signed-in users can call it, anonymous visitors cannot', f.proname,
         case when has_function_privilege('authenticated', f.oid, 'execute') and not has_function_privilege('anon', f.oid, 'execute') then 'OK' else 'FAIL' end,
         'authenticated ' || has_function_privilege('authenticated', f.oid, 'execute')::text || ', anon ' || has_function_privilege('anon', f.oid, 'execute')::text
  from fn f
  union all
  select 2, case n.kind when 'N' then 'new rule present' else 'earlier protection still present' end, n.fname || ': ' || n.label,
         case when f.oid is null then 'FAIL' when position(n.needle in f.prosrc) > 0 then 'OK' else 'FAIL' end,
         case when f.oid is null then 'function missing' when position(n.needle in f.prosrc) > 0 then '' else 'text not found: ' || n.needle end
  from needs n left join fn f on f.proname = n.fname
)
select grp, chk, item, result, detail from checks
  ) v_m02
),
req(kind, name) as (values ('function', 'clock_in'), ('function', 'create_initial_approval'), ('function', 'current_employee_id'), ('function', 'decide_leave_approval'), ('function', 'guard_profiles_self_update'), ('function', 'has_role'), ('function', 'inv_can_operate'), ('function', 'inv_can_view_stock'), ('function', 'inv_dispatch_to_project'), ('function', 'inv_idem_begin'), ('function', 'inv_is_founder'), ('function', 'inv_issue_to_employee'), ('function', 'inv_next_code'), ('function', 'inv_qty_free'), ('function', 'inv_refresh_request_status'), ('function', 'inv_require_enabled'), ('function', 'inv_require_user'), ('function', 'inv_reservation_take'), ('function', 'inv_return_from_project'), ('function', 'inv_unit_reserved_by'), ('function', 'pbx_accessible_company_ids'), ('function', 'pbx_approval_on_hold'), ('function', 'pbx_can_decide'), ('function', 'pbx_inbox'), ('function', 'pbx_require_user'), ('function', 'preflight_phase2b_v2_policy_status'), ('function', 'proj_block_task'), ('function', 'proj_can_manage'), ('function', 'proj_can_view_details'), ('function', 'proj_decide_scope_change'), ('function', 'proj_has_capability'), ('function', 'proj_is_founder'), ('function', 'proj_is_pm'), ('function', 'proj_my_notifications'), ('function', 'proj_notify'), ('function', 'proj_propose_scope_change'), ('function', 'proj_require_user'), ('function', 'proj_unblock_task'), ('function', 'recovery_eligible_approver_exists'), ('function', 'recovery_route_request'), ('function', 'resolve_approver'), ('function', 'resolve_approver_for_company'), ('function', 'resolve_role_holders'), ('function', 'seed_phase2b_policy_drafts'), ('function', 'set_account_status'), ('function', 'user_has_role'), ('function', 'validate_attendance_segment_inputs'), ('table', 'crm_company_grants'), ('table', 'inv_company_grants'), ('table', 'pbx_company_grants'), ('table', 'proj_company_grants')),
req_missing as (
  select r.kind, r.name from req r
  where (r.kind = 'function' and not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = r.name))
     or (r.kind = 'table' and to_regclass('public.' || r.name) is null)
),
packs as (
  select pack, count(*) as n, count(*) filter (where result = 'FAIL') as failing from prereq group by pack
),
mstate as (select item, value from cur where item like 'pre:m%' and item >= 'pre:m03'),
n_applied as (select count(*) as n from mstate where value = 'applied'),
digest_items as (select item, case when item like 'rows:%' and value ~ '^[0-9]+:' then split_part(value, ':', 1) || ':' || left(split_part(value, ':', 2), 16) when length(value) <= 16 then value else left(md5(value), 16) end as value from cur),
digest as (
  select (select md5(string_agg(item || '=' || value, ';' order by item)) from digest_items) as chk,
         (select jsonb_object_agg(item, value) from digest_items) as items
),
rows_out(ord, section, item, result, detail) as (
  select 10, 'A session', 'running as', '', current_user::text || ' (superuser=' || (select rolsuper::text from pg_roles where rolname = current_user) || ')'
  union all select 11, 'A session', 'server_version', '', version()
  union all select 12, 'A session', 'now (Dubai)', '', to_char(now() at time zone 'Asia/Dubai', 'YYYY-MM-DD HH24:MI:SS')
  union all select 100 + row_number() over (order by case pack when 'base' then 0 else substr(pack, 2)::int end), 'B prerequisites',
         case pack when 'base' then 'access grant rules migration 20261215000000 (its verify checks)' else 'launch migration ' || ltrim(substr(pack, 2), '0') || ' (its verify checks)' end,
         case when failing = 0 then 'PASS' else 'FAIL' end, n - failing || ' of ' || n || ' checks pass' || case when failing > 0 then ', ' || failing || ' failing (listed below)' else '' end
  from packs
  union all select 150, 'B prerequisites', 'failing check: ' || pack || ' / ' || chk || ': ' || item, 'FAIL', detail from prereq where result = 'FAIL'
  union all select 160, 'B prerequisites', 'objects migrations 3 to 14 build on (' || (select count(*) from req) || ' functions and tables)',
         case when exists (select 1 from req_missing) then 'FAIL' else 'PASS' end,
         case when exists (select 1 from req_missing) then 'MISSING: ' || (select string_agg(kind || ' ' || name, ', ' order by name) from req_missing) else 'all present' end
  union all select 170, 'B prerequisites', 'migrations 1 and 2 present (inv_issue_to_employee, proj_propose_scope_change)',
         case when (select count(*) from cur where item in ('pre:m01', 'pre:m02') and value = 'applied') = 2 then 'PASS' else 'FAIL' end,
         (select string_agg(item || ' ' || value, ', ' order by item) from cur where item in ('pre:m01', 'pre:m02'))
  union all select 200 + 3, 'C migrations 3 to 14', 'migration 3: deactivation sets is_active; routing skips inactive people; last CEO/CTO protections', case when (select value from cur where item = 'pre:m03') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m03') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 4, 'C migrations 3 to 14', 'migration 4: profiles: the deactivation reason is no longer readable directly; System Administrator function added', case when (select value from cur where item = 'pre:m04') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m04') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 5, 'C migrations 3 to 14', 'migration 5: attendance clock: project-lead candidates function', case when (select value from cur where item = 'pre:m05') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m05') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 6, 'C migrations 3 to 14', 'migration 6: Recovery Leave: decider inbox function', case when (select value from cur where item = 'pre:m06') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m06') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 7, 'C migrations 3 to 14', 'migration 7: policy status function: role check and no anonymous execute', case when (select value from cur where item = 'pre:m07') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m07') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 8, 'C migrations 3 to 14', 'migration 8: letters storage: the owning employee reads issued letters only', case when (select value from cur where item = 'pre:m08') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m08') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 9, 'C migrations 3 to 14', 'migration 9: approval routing is country-scoped', case when (select value from cur where item = 'pre:m09') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m09') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 10, 'C migrations 3 to 14', 'migration 10: scope decision: two narrow read functions', case when (select value from cur where item = 'pre:m10') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m10') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 11, 'C migrations 3 to 14', 'migration 11: budget decisions waiting: count function', case when (select value from cur where item = 'pre:m11') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m11') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 12, 'C migrations 3 to 14', 'migration 12: blocker: the Project Manager is told who was asked', case when (select value from cur where item = 'pre:m12') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m12') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 13, 'C migrations 3 to 14', 'migration 13: ask-for-access names the people who can grant it', case when (select value from cur where item = 'pre:m13') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m13') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 200 + 14, 'C migrations 3 to 14', 'migration 14: dispatch and return notes: tables, functions, guarded call in the movements, switch column (off)', case when (select value from cur where item = 'pre:m14') = 'absent' then 'PASS' else 'ALREADY APPLIED' end, case when (select value from cur where item = 'pre:m14') = 'absent' then 'not applied yet (expected)' else 'its marker is present now' end
  union all select 290, 'C migrations 3 to 14', 'state of migrations 3 to 14',
         case (select n from n_applied) when 0 then 'PASS' when 12 then 'ALREADY APPLIED' else 'PARTIALLY APPLIED' end,
         case (select n from n_applied) when 0 then 'none of the 12 is applied yet (clean start)'
              when 12 then 'all 12 are already in place: nothing to install; run file 90 (without a digest) to verify them'
              else (select n from n_applied) || ' of 12 are already in place: ' || (select string_agg(ltrim(substr(item, 6), 'm0'), ', ' order by item) from mstate where value = 'applied') end
  union all select 300 + row_number() over (order by item), 'D snapshot', 'table ' || substr(item, 6) || ' (rows : fingerprint)', 'INFO', value from cur where item like 'rows:%'
  union all select 400 + row_number() over (order by item), 'D snapshot', 'function fingerprint ' || substr(item, 4) || ' (migrations 1 and 2: must stay identical)', 'INFO', left(value, 16) from cur where item in ('fn:inv_issue_to_employee', 'fn:proj_propose_scope_change')
  union all select 450, 'D snapshot', 'scheduler (pg_cron job definitions)', 'INFO', (select value from cur where item = 'keep:scheduler: pg_cron job definitions (cron.job)')
  union all select 451, 'D snapshot', 'dispatch / return notes switch (companies with it ON)', 'INFO', (select value from cur where item like 'keep:companies with the dispatch-note switch ON%')
  union all select 480, 'D snapshot', 'digest items / checksum', 'INFO', (select count(*) from digest_items) || ' items, checksum ' || (select chk from digest)
  union all select 999, 'D snapshot', 'DIGEST (copy this one cell for file 90)', 'INFO', jsonb_build_object('v', 1, 'chk', (select chk from digest), 'items', (select items from digest))::text
),
verdict as (
  select case
    when exists (select 1 from prereq where result = 'FAIL') or exists (select 1 from req_missing) or (select count(*) from cur where item in ('pre:m01', 'pre:m02') and value = 'applied') < 2
      then 'FAIL: ' || ((select count(*) from prereq where result = 'FAIL') + (select count(*) from req_missing) + case when (select count(*) from cur where item in ('pre:m01', 'pre:m02') and value = 'applied') < 2 then 1 else 0 end)
           || ' prerequisite item(s) fail, see the rows marked FAIL. Do NOT run file 20. Send me this whole result.'
    when (select n from n_applied) = 0
      then 'PASS: every prerequisite is in place and migrations 3 to 14 are not applied yet. Copy the DIGEST cell (last row), then run file 20.'
    when (select n from n_applied) = 12
      then 'ALREADY APPLIED: all 12 migrations (3 to 14) are already in place. Nothing to install. Run file 90 (leave the digest empty) to verify them.'
    else 'PARTIALLY APPLIED: ' || (select n from n_applied) || ' of the 12 migrations (3 to 14) are already in place (' || (select string_agg(ltrim(substr(item, 6), 'm0'), ', ' order by item) from mstate where value = 'applied')
         || '). Send me this whole result BEFORE running file 20. (Running file 20 would still be safe, because every migration can be repeated; I want to confirm first why they are partly there.)'
  end as txt
)
select section, item, result, detail from (
  select 0 as ord, '0 RESULT' as section, 'read this first' as item, case when v.txt like 'PASS%' then 'PASS' when v.txt like 'FAIL%' then 'FAIL' else 'CHECK' end as result, v.txt as detail from verdict v
  union all select ord, section, item, result, detail from rows_out
) r
order by ord, item;
